'use strict'

import resource from '../../resource'
import { TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN } from '../../constant'
import { Enemy, STATE_HURT, randomInt, pick, drawImage } from './common'
import { Fireball } from './projectile'

// Lives in the water: comes up at a place of it, spits a fireball at Link, dives again. The sword
// only hurts it out of the water
const ZORA = { life: 2, contactDamage: 0.5 }
const MIN_UNDER_STEPS = 60
const MAX_UNDER_STEPS = 160
const EMERGE_STEPS = 32
const SURFACED_STEPS = 64
const SPIT_STEP = 24
const DIVE_STEPS = 20
const RIPPLE_FRAME_STEPS = 8

const STATE_UNDER = 'under'
const STATE_EMERGING = 'emerging'
const STATE_SURFACED = 'surfaced'
const STATE_DIVING = 'diving'

// Water tiles of the screen (the waterfalls apart)
export function findWater (map) {
  const cells = []
  for (let column = 0; column < TILES_PER_LINE; column++) {
    for (let line = 0; line < TILES_PER_COLUMN; line++) {
      const name = map.getTile(column, line)?.sprite?.name ?? ''
      if (name.startsWith('water') && !name.startsWith('waterfall')) {
        cells.push({ x: map.x + column * TILE_WIDTH, y: map.y + line * TILE_HEIGHT })
      }
    }
  }

  return cells
}

class Zora extends Enemy {
  constructor (type, water, random = Math.random) {
    const place = pick(random, water)
    super(type, place.x, place.y, ZORA, random)
    this.water = water
    this.wait = randomInt(random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
    this.setState(STATE_UNDER)
    this.facingUp = false
  }

  get isActive () {
    return this.state === STATE_SURFACED || this.state === STATE_HURT
  }

  // It stays in the water when hit
  canStandAt () {
    return false
  }

  act (map, link) {
    switch (this.state) {
      case STATE_UNDER:
        if (this.steps >= this.wait) {
          const place = pick(this.random, this.water)
          this.x = place.x
          this.y = place.y
          this.setState(STATE_EMERGING)
        }
        break
      case STATE_EMERGING:
        if (this.steps >= EMERGE_STEPS) {
          this.setState(STATE_SURFACED)
        }
        break
      case STATE_SURFACED:
        this.facingUp = link.y < this.y
        if (this.steps === SPIT_STEP) {
          map.projectiles.push(new Fireball(this.x, this.y, link))
        }
        if (this.steps >= SURFACED_STEPS) {
          this.setState(STATE_DIVING)
        }
        break
      case STATE_DIVING:
        if (this.steps >= DIVE_STEPS) {
          this.setState(STATE_UNDER)
          this.wait = randomInt(this.random, MIN_UNDER_STEPS, MAX_UNDER_STEPS)
        }
        break
    }
  }

  drawBody (context) {
    switch (this.state) {
      case STATE_UNDER:
        return
      case STATE_EMERGING:
      case STATE_DIVING:
        drawImage(context, resource.getSprite('zora_water_move'), Math.floor(this.steps / RIPPLE_FRAME_STEPS) % 2, this.x, this.y, this.width, this.height)
        return
    }
    drawImage(context, resource.getSprite('zora_move'), this.facingUp ? 1 : 0, this.x, this.y, this.width, this.height)
  }
}

export { Zora }
