'use strict'

import HitboxManager from '../service/hitbox-manager'
import { isBlocked } from '../service/collision'
import clock from '../service/clock'
import soundManager from '../service/sound-manager'
import resource from '../resource'
import { DIRECTION_EAST, DIRECTION_SOUTH, DIRECTION_WEST, LINK_DIRECTION_EAST, LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH, LINK_DIRECTION_WEST, LINK_ACTION_MOVE, LINK_ACTION_PICK, LINK_ACTION_USE, LINK_ACTION_USE_ITEM_A, LINK_ACTION_USE_ITEM_B, SPRITE_LINK_PREFIX, GAME_INTERVAL_PROCESS, SWORDS, SWORD_DAMAGES, SOUND_SWORD_SLASH, SOUND_LINK_HURT, OPPOSITE_DIRECTIONS, ITEM_SHIELD_MAGICAL, ITEM_BOMB, SOUND_BOMB_DROP, TILE_WIDTH, TILE_HEIGHT } from '../constant'
import { Inventory } from './inventory'
import { createKillRecord, breakKillSeries } from './drop'
import { Item } from './item'
import { Bomb } from './bomb'

const EVENT_ITEM_A_CHANGED = 'item_a_changed'
const EVENT_ITEM_B_CHANGED = 'item_b_changed'

// How long Link holds his sword out; he can't move meanwhile
const SWORD_DURATION = 250
// Putting a bomb down: 12 frames, measured in the ROM
const BOMB_DURATION = 200

const SPRITE_WIDTH = 32
const SPRITE_HEIGHT = 32

const HITBOX_DELTA = 2
// Pixels per second: 1.5 NES pixels per frame at 60 frames per second, doubled for the display
const SPEED = 180
// How far Link is nudged sideways to get round a corner into an opening (half a tile)
const CORNER_ASSIST_DISTANCE = 16
// When hurt, Link is pushed back (in game steps and pixels per step), then flickers, invincible
const KNOCKBACK_STEPS = 8
const KNOCKBACK_SPEED = 8
const INVINCIBLE_STEPS = 48
// What enemies and rocks touch: the sprite, slightly smaller
const BODY_INSET = 4
// What the sword reaches, in front of Link, while he holds it out
const SWORD_REACH = 28
const SWORD_WIDTH = 16

const DIRECTION_VECTORS = {
  [LINK_DIRECTION_EAST]: [1, 0],
  [LINK_DIRECTION_NORTH]: [0, -1],
  [LINK_DIRECTION_SOUTH]: [0, 1],
  [LINK_DIRECTION_WEST]: [-1, 0]
}

// An item of the B button, as shown in the menus
export function createBItem (name) {
  return new Item(name, 0, 0, 0, 0, TILE_WIDTH, TILE_HEIGHT, resource.getSprite(`item_${name}`))
}

class Link extends EventTarget {
  constructor (x, y, width, height) {
    super()

    this.x = x
    this.y = y
    this.width = SPRITE_WIDTH
    this.height = SPRITE_HEIGHT

    this.speed = Math.round(SPEED * GAME_INTERVAL_PROCESS / 1000) // Pixels per game step
    this.action = LINK_ACTION_MOVE
    this.direction = LINK_DIRECTION_SOUTH
    this.clipX = 0
    this.clipY = 0

    this.inventory = new Inventory()

    this.totalLife = 3
    this.currentLife = 3

    this.items = []
    this._itemA = undefined
    this._itemB = undefined

    this.actions = []
    this.usingItem = false
    this.swordSwing = 0 // Each thrust hits an enemy once

    this.knockback = undefined
    this.invincibleSteps = 0
    // Enemies killed, for what they leave behind them
    this.killRecord = createKillRecord()
  }

  static get EVENT_ITEM_A_CHANGED () {
    return EVENT_ITEM_A_CHANGED
  }

  static get EVENT_ITEM_B_CHANGED () {
    return EVENT_ITEM_B_CHANGED
  }

  canPick (item) {
    if (!item.enabled) {
      return false
    }

    const collision = HitboxManager.computeHitboxesCollision(item.hitbox, this.hitbox)
    if (!collision) {
      return false
    }

    if (item.price && this.inventory.rupees < item.price) {
      return false
    }

    // TODO add swordconditions

    return true
  }

  // Keeps a picked item. For now only swords (they go on the A button, as in the original game) and
  // bombs (4, as from the merchant)
  pickItem (item) {
    if (item.name === ITEM_BOMB) {
      this.addBombs(4)
      return
    }
    if (!SWORDS.includes(item.name)) {
      return
    }
    const pickedItem = item.clone()
    pickedItem.price = undefined
    this.addItem(pickedItem)
    this.itemA = pickedItem
  }

  // Sword thrust: Link stands still with the sword out for SWORD_DURATION
  useItemA () {
    if (this.itemA === undefined || this.usingItem) {
      return
    }
    this.usingItem = true
    this.swordSwing++
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_A
    soundManager.play(resource.getSound(SOUND_SWORD_SLASH))
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, SWORD_DURATION)
  }

  get swordDamage () {
    return SWORD_DAMAGES[this.itemA?.name] ?? 0
  }

  getBodyBox () {
    return { x: this.x + BODY_INSET, y: this.y + BODY_INSET, width: this.width - 2 * BODY_INSET, height: this.height - 2 * BODY_INSET }
  }

  // The blade in front of Link during a thrust, undefined otherwise
  getSwordBox () {
    if (!this.usingItem || this.action !== LINK_ACTION_USE_ITEM_A) {
      return undefined
    }
    const across = (this.width - SWORD_WIDTH) / 2
    switch (this.direction) {
      case LINK_DIRECTION_NORTH:
        return { x: this.x + across, y: this.y - SWORD_REACH, width: SWORD_WIDTH, height: SWORD_REACH }
      case LINK_DIRECTION_SOUTH:
        return { x: this.x + across, y: this.y + this.height, width: SWORD_WIDTH, height: SWORD_REACH }
      case LINK_DIRECTION_EAST:
        return { x: this.x + this.width, y: this.y + across, width: SWORD_REACH, height: SWORD_WIDTH }
      case LINK_DIRECTION_WEST:
        return { x: this.x - SWORD_REACH, y: this.y + across, width: SWORD_REACH, height: SWORD_WIDTH }
    }
  }

  // The shield stops what comes at Link from the front, unless he is busy with his sword or pushed back
  // Some projectiles (lynel swords, fireballs) are only stopped by this one
  get hasMagicalShield () {
    return this.inventory.shield === ITEM_SHIELD_MAGICAL
  }

  canBlock (direction) {
    return !this.usingItem && !this.knockback && this.direction === OPPOSITE_DIRECTIONS[direction]
  }

  // Hurt by something at source (a box): loses life and is pushed away from it. True if he was hurt
  hurt (damage, source) {
    if (this.invincibleSteps > 0) {
      return false
    }
    this.currentLife = Math.max(0, this.currentLife - damage)
    this.invincibleSteps = INVINCIBLE_STEPS
    breakKillSeries(this.killRecord)
    soundManager.play(resource.getSound(SOUND_LINK_HURT))
    const dx = this.x + this.width / 2 - (source.x + source.width / 2)
    const dy = this.y + this.height / 2 - (source.y + source.height / 2)
    const vector = Math.abs(dx) >= Math.abs(dy) ? [Math.sign(dx) || 1, 0] : [0, Math.sign(dy) || 1]
    this.knockback = { vector, steps: KNOCKBACK_STEPS }
    this.stopWalking()

    return true
  }

  // One game step of what happens to Link on his own: being pushed back, invincibility running out.
  // He stays on the screen when pushed (no screen change)
  update (map) {
    if (this.invincibleSteps > 0) {
      this.invincibleSteps--
    }
    if (!this.knockback) {
      return
    }
    const [dx, dy] = this.knockback.vector
    for (let i = 0; i < KNOCKBACK_SPEED; i++) {
      const x = this.x + dx
      const y = this.y + dy
      const inside = map.x <= x && x + this.width <= map.x + map.width && map.y <= y && y + this.height <= map.y + map.height
      if (!inside || !this.moveBy(map, dx, dy)) {
        break
      }
    }
    this.hitbox = HitboxManager.compute(this)
    this.knockback.steps--
    if (this.knockback.steps <= 0) {
      this.knockback = undefined
    }
  }

  // The item of the B button: only bombs for now
  useItemB (map) {
    if (this.itemB?.name === ITEM_BOMB) {
      this.putBomb(map)
    }
  }

  // A bomb on the ground, one tile in front of Link (even in a wall), one at a time
  putBomb (map) {
    if (this.usingItem || this.inventory.bombs <= 0 || map.bombs.length > 0) {
      return
    }
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    map.bombs.push(new Bomb(this.x + dx * TILE_WIDTH, this.y + dy * TILE_HEIGHT))
    this.inventory.bombs--
    if (this.inventory.bombs === 0) {
      this.itemB = undefined
    }
    soundManager.play(resource.getSound(SOUND_BOMB_DROP))
    this.usingItem = true
    this.stopWalking()
    this.action = LINK_ACTION_USE_ITEM_B
    clock.delay(() => {
      this.usingItem = false
      this.action = LINK_ACTION_MOVE
    }, BOMB_DURATION)
  }

  // Bombs picked or bought, up to what the bag holds. With nothing on B, they go there
  addBombs (count) {
    this.inventory.bombs = Math.min(this.inventory.maxBombs, this.inventory.bombs + count)
    if (this.inventory.bombs > 0 && this.itemB === undefined) {
      this.itemB = createBItem(ITEM_BOMB)
    }
  }

  // Collision box: the lower half of the sprite (his feet), slightly smaller than a tile
  getHitbox (x = this.x, y = this.y) {
    return {
      x: x + HITBOX_DELTA,
      y: y + (this.height / 2) + HITBOX_DELTA,
      width: this.width - 2 * HITBOX_DELTA,
      height: (this.height / 2) - 2 * HITBOX_DELTA
    }
  }

  // Moves pixel by pixel, so Link stops flush against walls. When the way is blocked but an
  // opening is close on the side (gap between two blocks, cave entrance, diagonal wall),
  // Link slides towards it instead of being stuck, as in the original game.
  move (map, direction) {
    this.direction = direction
    const [dx, dy] = DIRECTION_VECTORS[direction]
    for (let i = 0; i < this.speed; i++) {
      if (this.moveBy(map, dx, dy)) {
        continue
      }
      const nudge = this.findOpening(map, dx, dy)
      if (!nudge || !this.moveBy(map, nudge[0], nudge[1])) {
        break
      }
    }

    this.hitbox = HitboxManager.compute(this)
  }

  moveBy (map, dx, dy) {
    if (isBlocked(map, this.getHitbox(this.x + dx, this.y + dy))) {
      return false
    }
    this.x += dx
    this.y += dy

    return true
  }

  // Nearest sideways shift (within CORNER_ASSIST_DISTANCE) from which Link could go on.
  // Returns the 1 pixel step towards it; undefined when there is none, or when both sides
  // are equally close (Link is centred on an obstacle: no side is preferred).
  findOpening (map, dx, dy) {
    const sideX = Math.abs(dy)
    const sideY = Math.abs(dx)
    for (let distance = 1; distance <= CORNER_ASSIST_DISTANCE; distance++) {
      const openSides = [1, -1].filter(sign => {
        const x = this.x + sideX * sign * distance
        const y = this.y + sideY * sign * distance
        return !isBlocked(map, this.getHitbox(x, y)) && !isBlocked(map, this.getHitbox(x + dx, y + dy))
      })
      if (openSides.length === 1) {
        return [sideX * openSides[0], sideY * openSides[0]]
      }
      if (openSides.length === 2) {
        return undefined
      }
    }

    return undefined
  }

  startWalking () {
    const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
    if (!sprite) {
      console.log(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
      return
    }
    sprite.start()
  }

  stopWalking () {
    const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
    if (!sprite) {
      console.log(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${this.action}`)
      return
    }
    sprite.stop()
  }

  // Standing still whatever the direction, on the first image of the walk: each direction has its own
  // sprite, which may still be animated after Link turned (he spins when he dies)
  standStill () {
    for (const direction of Object.keys(OPPOSITE_DIRECTIONS)) {
      const sprite = resource.getSprite(`${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${direction}_${this.inventory.shield}_${LINK_ACTION_MOVE}`)
      sprite?.stop()
      if (sprite) {
        sprite.currentImageIndex = 0
      }
    }
  }

  drawSword (context, offsetX, offsetY) {
    context.save()
    const itemWidth = this.itemA.sprite.width
    const itemHeight = this.itemA.sprite.height
    const linkX = offsetX + this.x + this.clipX
    const linkY = offsetY + this.y + this.clipY
    const linkWidth = this.width - this.clipX
    const linkHeight = this.height - this.clipY
    // Relative to the current transform (top menu and map offsets), around Link's centre
    context.translate(linkX + linkWidth / 2, linkY + linkHeight / 2)
    let deltaX = 0
    const deltaY = -3 / 4 * linkHeight
    if (this.direction === DIRECTION_EAST) {
      context.rotate(90 * Math.PI / 180)
      deltaX = 1 / 8 * linkWidth
    }
    if (this.direction === DIRECTION_SOUTH) {
      context.rotate(180 * Math.PI / 180)
    }
    if (this.direction === DIRECTION_WEST) {
      context.rotate(-90 * Math.PI / 180)
      deltaX = -1 / 8 * linkWidth
    }
    this.itemA.sprite.draw(context, 0, 0, itemWidth, itemHeight, -linkWidth / 2 + deltaX, -linkHeight / 2 + deltaY, itemWidth, itemHeight)
    context.restore()
  }

  draw (context, offsetX, offsetY, drawingAction) {
    // Flickers while invincible
    if (this.invincibleSteps > 0 && Math.floor(this.invincibleSteps / 2) % 2 === 1) {
      return
    }

    if (drawingAction === LINK_ACTION_USE_ITEM_A) {
      this.drawSword(context, offsetX, offsetY)
    }

    const spriteName = this.getSpriteName(drawingAction)
    // Not every ring / shield has its own sprite for each action: fall back on the walking one
    const sprite = resource.getSprite(spriteName) ?? resource.getSprite(this.getSpriteName(LINK_ACTION_MOVE))
    if (!sprite) {
      console.log(spriteName)
      return
    }
    sprite.draw(
      context,
      0, 0, this.width - this.clipX, this.height - this.clipY,
      offsetX + this.x + this.clipX, offsetY + this.y + this.clipY, this.width - this.clipX, this.height - this.clipY
    )
  }

  getSpriteName (action) {
    switch (action) {
      case LINK_ACTION_PICK:
        return `${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${LINK_ACTION_PICK}`
      case LINK_ACTION_USE_ITEM_A:
      case LINK_ACTION_USE_ITEM_B:
        return `${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${LINK_ACTION_USE}`
      case LINK_ACTION_MOVE:
        return `${SPRITE_LINK_PREFIX}_${this.inventory.ring}_${this.direction}_${this.inventory.shield}_${LINK_ACTION_MOVE}`
    }
  }

  addItem (item) {
    this.items.push(item)
  }

  // Items are compared by name (wooden_sword…): the picked item is a copy of the one on the map
  removeItem (item) {
    this.items = this.items.filter(ownedItem => ownedItem.name !== item.name)
  }

  hasItem (item) {
    return this.items.some(ownedItem => ownedItem.name === item.name)
  }

  addAction (action) {
    if (this.actions.indexOf(action) === -1) {
      this.actions.push(action)
    }
  }

  hasAction (action) {
    return this.actions.indexOf(action) > -1
  }

  removeAction (action) {
    const index = this.actions.indexOf(action)
    if (index > -1) {
      this.actions.splice(index, 1)
    }
  }

  resetActions () {
    this.actions = []
  }

  get itemA () {
    return this._itemA
  }

  set itemA (item) {
    this._itemA = item
    this.dispatchEvent(new Event(EVENT_ITEM_A_CHANGED))
  }

  get itemB () {
    return this._itemB
  }

  set itemB (item) {
    this._itemB = item
    this.dispatchEvent(new Event(EVENT_ITEM_B_CHANGED))
  }
}

export default Link
